L24_1.m_Talk_VTN = "Nghe thì khá sáo rỗng, nhưng mà thật sự cảm động!"
L24_1.m_Talk_SCN = "虽然有些俗套，但还是很扣人心弦呢！"
L24_1.m_Talk_DEU = "It may be a cliché, but it’s just so touching!"
L24_1.m_Talk_FRA = "It may be a cliché, but it’s just so touching!"
