L32_1.m_Talk_KOREA = "<color=#ffd34c>…한심하군, 1호. 겨우 이런 걸로 쓰러지는 거냐?</color>"
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "<color=#ffd34c>……情けないな、1号。こんなところで倒れるとは。</color>"
L32_1.m_Talk_ENG = "<color=#ffd34c>Number 1, you’re giving up just for this?</color>"
L32_1.m_Talk_TWN = "<color=#ffd34c>…真令人失望，1號這樣就倒下啦</color>"
L32_1.m_Talk_THA = "<color=#ffd34c>หมายเลข 1 นี่ยอมแพ้เพราะเรื่องแค่นี้เหรอ?</color>"
L32_1.m_Talk_VTN = "<color=#ffd34c>Số 1, cậu sẽ từ bỏ chỉ vì chuyện này sao?</color>"
L32_1.m_Talk_SCN = "<color=#ffd34c>……真没用，1号。你就这么轻易倒下了？</color>"
L32_1.m_Talk_DEU = "<color=#ffd34c>Number 1, you’re giving up just for this?</color>"
L32_1.m_Talk_FRA = "<color=#ffd34c>Number 1, you’re giving up just for this?</color>"
