L36_1.m_Crash = 30
L36_1.m_Talk_KOREA = "우왓, 완전 똑같아! 어떻게 한 거야? 리더, 연기도 잘하는구나?"
L36_1.m_fTalkTime = 0.03
L36_1.m_Talk_JPN = "うわっ、そっくり！　リーダーってば演技もできるんだね！"
L36_1.m_Talk_ENG = "You sound exactly same as the show! How did you do that? You’re pretty good at acting, leader!"
L36_1.m_Talk_THA = "คุณพูดเหมือนในหนังเป๊ะเลยค่ะ! ทำได้ยังไงอะ? คุณแสดงเก่งนะเนี่ย หัวหน้า!"
L36_1.m_Talk_VTN = "Giọng chị nghe giống hệt trong này luôn! Sao chị làm được thế? Thủ lĩnh, chị giỏi diễn xuất phết đấy!"
L36_1.m_Talk_SCN = "唔哇，学得超像耶！怎么做到的？队长，原来你的演技这么好？"
L36_1.m_Talk_DEU = "You sound exactly same as the show! How did you do that? You’re pretty good at acting, leader!"
L36_1.m_Talk_FRA = "You sound exactly same as the show! How did you do that? You’re pretty good at acting, leader!"
