L37_1.m_Talk_KOREA = "그보다 어땠어? 어땠어? 가면 카운터 2호의 등장 장면?"
L37_1.m_fTalkTime = 0.03
L37_1.m_Talk_JPN = "それより、どうだった？　仮面カウンター2号の登場シーン！"
L37_1.m_Talk_ENG = "What do you think? The part where the number 2 comes to rescue."
L38_1 = "不過，怎麼樣？怎麼樣？你覺得蒙面制裁者2號出場的這場戲如何？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เธอคิดว่าไง? ฉากที่หมายเลข 2 เข้ามาช่วยน่ะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chị nghĩ sao? Về phân đoạn số 2 đến giải cứu ấy."
L37_1.m_Talk_VTN = L38_1
L38_1 = "对了，对了，你觉得假面制裁者2号的出场画面怎么样？"
L37_1.m_Talk_SCN = L38_1
L37_1.m_Talk_DEU = "What do you think? The part where the number 2 comes to rescue."
L37_1.m_Talk_FRA = "What do you think? The part where the number 2 comes to rescue."
