L47_1 = "…그렇게 해서 함정에 빠진 1호를 2호가 구해주면서 두 사람이 친구가 된 거지."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "……こうして、罠に嵌った1号を2号が助けたところから二人の友情が始まったわけ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "...So number 2 saved number 1 when number 1 fell into a trap, and they became friends."
L46_1.m_Talk_ENG = L47_1
L47_1 = "…所以在2號拯救陷入危險的1號的同時，他們就變成朋友啦～"
L46_1.m_Talk_TWN = L47_1
L47_1 = "...แล้วหมายเลข 2 ก็ช่วยหมายเลข 1 ตอนที่หมายเลข 1 ติดกับดัก แล้วพวกเขาก็กลายเป็นเพื่อนกัน"
L46_1.m_Talk_THA = L47_1
L47_1 = "...Thế nên số 2 đã cứu số 1 khi số 1 rơi vào bẫy, và thế là họ trở thành bạn."
L46_1.m_Talk_VTN = L47_1
L47_1 = "……如此一来，2号救出了落入陷阱的1号，两个人就这样成为了好朋友。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "...So number 2 saved number 1 when number 1 fell into a trap, and they became friends."
L46_1.m_Talk_DEU = L47_1
L47_1 = "...So number 2 saved number 1 when number 1 fell into a trap, and they became friends."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "COUNTERCASE_ALPHA_JIA_NORMAL_1@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 31411
L47_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_IDLE"
L47_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L47_1.m_Pos = "L"
L48_1 = "아하, 할아버님께서도 가르쳐 주신 적 있어요. 곤경에 처한 사람을 외면하지 말라고요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "なるほど、お祖父様に言われたことがあります。困っている人を見捨ててはいけないと。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Oh, my grandfather taught me that I should help people in trouble."
L47_1.m_Talk_ENG = L48_1
L48_1 = "喔喔～我爺爺也有跟我說過，不可以對陷入困境的人視而不見。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "อ้อ คุณปู่ของฉันก็เคยสอนว่าฉันต้องช่วยเหลือคนที่เดือดร้อน"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ồ, ông của chị cũng từng nói rằng chị phải giúp đỡ khi thấy người khác gặp rắc rối."
L47_1.m_Talk_VTN = L48_1
L48_1 = "啊哈，爷爷曾经也说过，不能对陷入困境的人视而不见。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Oh, my grandfather taught me that I should help people in trouble."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Oh, my grandfather taught me that I should help people in trouble."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
