L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 31411
L48_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L48_1.m_Pos = "R"
L49_1 = "그래! <color=#ffd34c>옛말에 어려울 때 친구가 진짜 친구다</color>라는 말도 있잖아?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そう、それ！　<color=#ffd34c>ピンチの時の友こそ真の友</color>って言うでしょ？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Exactly! <color=#ffd34c>A friend in need is a friend indeed.</color>"
L48_1.m_Talk_ENG = L49_1
L49_1 = "沒錯！<color=#ffd34c>不是有句話說，患難見真情</color>嗎？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ใช่ค่ะ! <color=#ffd34c>เพื่อนที่ช่วยเหลือกันในยามยากคือเพื่อนแท้</color>"
L48_1.m_Talk_THA = L49_1
L49_1 = "Chính xác! <color=#ffd34c>Một người bạn trong lúc hoạn nạn mới là một người bạn chân chính.</color>"
L48_1.m_Talk_VTN = L49_1
L49_1 = "是啊！俗话说，<color=#ffd34c>患难见真情嘛</color>！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Exactly! <color=#ffd34c>A friend in need is a friend indeed.</color>"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Exactly! <color=#ffd34c>A friend in need is a friend indeed.</color>"
L48_1.m_Talk_FRA = L49_1
