L3_1 = "…다시 말해, <color=#ffd34c>어려움에 처한 사람을 돕다 보면, 진짜 친구가 된다</color>는 말이군요!"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "つまり……<color=#ffd34c>困っている人を助けることで、真の友だちになる</color>ということですね！"
L2_1.m_Talk_JPN = L3_1
L3_1 = "So what you mean is that <color=#ffd34c>if you help people in need, you become real friends</color>!"
L2_1.m_Talk_ENG = L3_1
L3_1 = "…合起來就是， <color=#ffd34c>幫助陷入困境的人，就會成為患難之交</color>！"
L2_1.m_Talk_TWN = L3_1
L3_1 = "หมายความว่า<color=#ffd34c>ถ้าเราช่วยคนที่เดือดร้อน เราก็จะกลายเป็นเพื่อนกันจริงๆ เหรอ</color>!"
L2_1.m_Talk_THA = L3_1
L3_1 = "Thế nên ý của em là <color=#ffd34c>nếu em giúp đỡ người đang cần trợ giúp, thì bọn em sẽ trở thành những người bạn thật sự</color>!"
L2_1.m_Talk_VTN = L3_1
L3_1 = "……那就是说，<color=#ffd34c>在别人遇到困难时伸出援手就能成为朋友</color>，对吧？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "So what you mean is that <color=#ffd34c>if you help people in need, you become real friends</color>!"
L2_1.m_Talk_DEU = L3_1
L3_1 = "So what you mean is that <color=#ffd34c>if you help people in need, you become real friends</color>!"
L2_1.m_Talk_FRA = L3_1
