L7_1 = "COUNTERCASE_ALPHA_JIA_NORMAL_1@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 31411
L6_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_1"
L6_1.m_bWaitClick = true
