L6_1.m_Face = "UNIT_PRIDE"
L6_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L6_1.m_Pos = "R"
L7_1 = "뭐, 맞아! 가면 카운터처럼 다른 사람들을 계속 돕다보면, 친구들도 잔뜩 생기겠지!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "きっと、そうだよ！　仮面カウンターみたいに人々を助けることで、友だちもたくさんできるんだと思う！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Yeah! If you keep helping people like the Masked Counter, I’m sure you’ll end up with a lot of friends!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "就是這樣啦！只要像蒙面制裁者一樣，常常幫助人的話，就會有很多朋友！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ใช่แล้ว! ถ้าคุณช่วยคนอย่างเคาน์เตอร์หน้ากากยอดมนุษย์ไปเรื่อยๆ ฉันมั่นใจว่าสุดท้ายแล้วคุณจะมีเพื่อนเยอะแยะเลยค่ะ!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Phải rồi! Nếu chị giúp đỡ người khác giống như Counter Giấu Mặt, em chắc chắn rằng chị sẽ có rất nhiều bạn đấy!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "嗯，没错！就像假面制裁者那样一直帮助别人，就会交到很多好朋友！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Yeah! If you keep helping people like the Masked Counter, I’m sure you’ll end up with a lot of friends!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Yeah! If you keep helping people like the Masked Counter, I’m sure you’ll end up with a lot of friends!"
L6_1.m_Talk_FRA = L7_1
