L8_1.m_Face = "UNIT_LAUGH"
L8_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "그렇구나, 제가 또 하나 배웠네요. 고마워요, 새롬 씨."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "そうなのですね、また一つ学びました。ありがとうございます、アサネさん。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I see, thank you for the lesson, Saerom."
L8_1.m_Talk_ENG = L9_1
L9_1 = "原來如此，又學到了。謝謝芷倫。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เข้าใจแล้ว ขอบคุณสำหรับบทเรียนนะ แซรม"
L8_1.m_Talk_THA = L9_1
L9_1 = "Chị hiểu rồi, cảm ơn vì bài học Saerom nhé."
L8_1.m_Talk_VTN = L9_1
L9_1 = "原来如此，我又学到了新东西呢。谢谢你，绫音。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "I see, thank you for the lesson, Saerom."
L8_1.m_Talk_DEU = L9_1
L9_1 = "I see, thank you for the lesson, Saerom."
