L14_1 = "<color=#ffd34c>어려움에 처한 사람을 돕다 보면, 진짜 친구가 된다</color>라…"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "<color=#ffd34c>困っている人を助けることで、真の友だちになる</color>、か……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "<color=#ffd34c>You help people in need, you become real friends</color>..."
L13_1.m_Talk_ENG = L14_1
L14_1 = "<color=#ffd34c>幫助陷入困境的人，就會成為患難之交</color>…"
L13_1.m_Talk_TWN = L14_1
L14_1 = "<color=#ffd34c>ถ้าเราช่วยคนที่เดือดร้อน เราก็จะกลายเป็นเพื่อนกันจริงๆ เหรอ</color>..."
L13_1.m_Talk_THA = L14_1
L14_1 = "<color=#ffd34c>Nếu em giúp đỡ người đang cần trợ giúp, thì bọn em sẽ trở thành những người bạn thật sự</color>..."
L13_1.m_Talk_VTN = L14_1
L14_1 = "<color=#ffd34c>在别人遇到困难时伸出援手就能成为朋友</color>……"
L13_1.m_Talk_SCN = L14_1
L14_1 = "<color=#ffd34c>You help people in need, you become real friends</color>..."
L13_1.m_Talk_DEU = L14_1
L14_1 = "<color=#ffd34c>You help people in need, you become real friends</color>..."
L13_1.m_Talk_FRA = L14_1
