L15_1 = "COUNTERCASE_ALPHA_JIA_NORMAL_1@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 31411
L14_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L14_1.m_Pos = "C"
L15_1 = "…이 간단한 걸 왜 지금껏 눈치채지 못했을까?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "……こんなに簡単なことに、どうして今まで気づかなかったんでしょう。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "It’s so simple, why didn’t I realize that before?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "…這麼簡單的道理，我以前怎麼都沒發現呢？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ง่ายจัง ทำไมฉันคิดไม่ได้มาก่อนนะ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Chuyện thật đơn giản, sao trước đây mình không nhận ra nhỉ?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "……这么简单的道理，我为什么到现在才知道？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "It’s so simple, why didn’t I realize that before?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "It’s so simple, why didn’t I realize that before?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "COUNTERCASE_ALPHA_JIA_NORMAL_1@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 31411
L15_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_IDLE"
L15_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "그래, 어떤 일이든 생각났을 때, 바로바로 하지 않으면 나중에 후회한다고 할아버님께서 말씀하셨지?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "思い立ったが吉日。何かを思いついた時、すぐ行動しないと後で後悔するとお祖父様も言っていました。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Yes, my grandfather said, you should do what comes to your mind right away, or you’ll regret it later."
L15_1.m_Talk_ENG = L16_1
L16_1 = "沒錯，我爺爺也說過，不論想到任何事，若沒有馬上去做，之後一定會後悔。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ใช่แล้ว ปู่ของฉันเคยบอกว่าฉันควรทำสิ่งที่แวบขึ้นมาในความคิดทันที มิเช่นนั้นจะเสียใจภายหลัง"
L15_1.m_Talk_THA = L16_1
L16_1 = "Đúng vậy, ông mình từng nói, cháu nên làm theo suy nghĩ đầu tiên nảy ra trong đầu cháu, hoặc cháu sẽ hối hận."
L15_1.m_Talk_VTN = L16_1
L16_1 = "不错，爷爷也说过，不管什么事想到就要立即付诸行动，不然就会后悔。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Yes, my grandfather said, you should do what comes to your mind right away, or you’ll regret it later."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Yes, my grandfather said, you should do what comes to your mind right away, or you’ll regret it later."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
