L32_1 = "안녕하세요~ 여러분! 이쪽은 하트 베리의 차기 리더~ 루미 씨!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "皆さん、こんにちは～！　こちらはハートベリーの次期リーダー、ルミさんです！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Hello, everyone! This is the next leader of HRT Berry, Lumi!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "各位觀眾大家好～！這位是愛心莓果下一任的隊長～魯米！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "สวัสดีค่ะ ทุกคน! นี่คือหัวหน้า HRT เบอร์รี่คนถัดไป รูมีค่ะ!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Xin chào mọi người! Đây là nhóm trưởng tiếp theo của HRT Berry, Lumi!"
