L46_1.m_Talk_TWN = L47_1
L47_1 = "แต่เราเป็นเพื่อนกันนี่ ฉันอยากช่วยมาย่า..."
L46_1.m_Talk_THA = L47_1
L47_1 = "Nhưng bọn tôi là bạn, tôi chỉ muốn giúp Maya..."
