L15_1.m_CharStrID = L16_1
L16_1 = "R_M_I"
L15_1.m_Pos = L16_1
L16_1 = "곤란해 보이는 사람을 최대한 많이 도우시려고 증강현실 기술을 사용하셨다… 이 말씀이시군요?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "困っている人をなるべく多く助けようと、拡張現実技術を使用した、ということですね？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "So you activated the Augmented Reality skill to help as many people as possible?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "意思是，你為了盡全力幫助那些看似遇到困難的人，還不惜召喚增強具現體…是這個意思對吧？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "คุณเปิดใช้สกิลอ็อกเมนเต็ดเรียลลิตี้เพื่อช่วยคนให้มากที่สุดใช่มั้ย?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Thế là cô đã Kích hoạt Thực Tế Tăng Cường để giúp được nhiều người nhất có thể?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "你为了更多地帮助有困难的人，所以使用了增强现实技术……是这样吗？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "So you activated the Augmented Reality skill to help as many people as possible?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "So you activated the Augmented Reality skill to help as many people as possible?"
L15_1.m_Talk_FRA = L16_1
