L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "똑같은 사람이 여러 곳에서 사라졌다는 신고를 받고 무슨 소리인가 싶었는데…"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "同じ人がいろんな場所から消えたという通報があったから、なんのことかと思えば……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I was surprised when I heard the report that similar-looking people all disappeared simultaneously..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "我們接獲通報，說長得一模一樣的人，從好多個地方消失不見。我還想說這是在鬼扯什麼…"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ฉันแปลกใจตอนได้ยินรายงานว่ามีคนหน้าตาคล้ายๆ กันพร้อมใจกันหายตัวไปพร้อมๆ กัน..."
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi đã rất ngạc nhiên khi nghe báo cáo về những người trông giống nhau đồng loạt biến mất..."
L17_1.m_Talk_VTN = L18_1
L18_1 = "我接到举报说许多长得一模一样的人从多个地方一起消失了，还以为是恶作剧呢……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "I was surprised when I heard the report that similar-looking people all disappeared simultaneously..."
L17_1.m_Talk_DEU = L18_1
L18_1 = "I was surprised when I heard the report that similar-looking people all disappeared simultaneously..."
L17_1.m_Talk_FRA = L18_1
