L29_1 = "할아버님은 언젠가 저에게도 저를 있는 그대로 받아들여 줄 사람이 생길 거라고 했지만…"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "お祖父様はいつか私にも、ありのままの私を受け入れてくれる人が現れると言いましたが……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "My grandfather said that someday I would find someone who will like me for what I am..."
L28_1.m_Talk_ENG = L29_1
L29_1 = "雖然爺爺說過，總有一天會有那麼一個人，可以接納原本的我…"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ปู่ของฉันเคยบอกว่าสักวันฉันจะได้พบคนที่ชอบฉันในแบบที่ฉันเป็น..."
L28_1.m_Talk_THA = L29_1
L29_1 = "Ông mình từng nói rằng một ngày nào đó, mình sẽ tìm được người yêu quý mình vì chính con người mình..."
L28_1.m_Talk_VTN = L29_1
L29_1 = "爷爷说过，总有一天我也能遇到真心愿意和我交朋友的人……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "My grandfather said that someday I would find someone who will like me for what I am..."
L28_1.m_Talk_DEU = L29_1
L29_1 = "My grandfather said that someday I would find someone who will like me for what I am..."
